import 'package:flutter/material.dart';// import 'dart:ui' as ui;import 'package:flutter_bloc/flutter_bloc.dart';import 'package:zan/Config/app_config.dart';import '../../Core/Storage/Local/local_storage_keys.dart';import '../../Core/Storage/Local/local_storage_service.dart';class SettingsCubit extends Cubit<SettingsState> with WidgetsBindingObserver {  SettingsCubit() : super(SettingsState(locale: AppConfig.languageMain)) {    WidgetsBinding.instance.addObserver(this);    // _updateThemeMode();    _updateLanguage();  }  @override  Future<void> close() {    WidgetsBinding.instance.removeObserver(this);    return super.close();  }  @override  void didChangePlatformBrightness() {    _updateThemeMode();  }  void _updateThemeMode() {    // final brightness = ui.PlatformDispatcher.instance.platformBrightness;    // final systemThemeMode =    // brightness == Brightness.dark ? ThemeMode.dark : ThemeMode.light;    // emit(state.copyWith(themeMode: systemThemeMode));  }  void _updateLanguage() async {    // final locale = ui.PlatformDispatcher.instance.locale;    // if (locale.languageCode == 'ar') {    //   emit(state.copyWith(locale: Locale('ar')));    // } else {    //   emit(state.copyWith(locale: Locale('en')));    // }    final localeString = await LocalStorageService.getValue(      LocalStorageKeys.selectedLanguage,      defaultValue: false,    );    if (localeString == false) return;    emit(      state.copyWith(        locale: Locale(localeString),      ),    );  }  void toggleTheme() {    emit(state.copyWith(      themeMode:          state.themeMode == ThemeMode.light ? ThemeMode.dark : ThemeMode.light,    ));  }  void changeLanguage(Locale locale) {    emit(state.copyWith(locale: locale));  }}@immutableclass SettingsState {  final ThemeMode themeMode;  final Locale locale;  const SettingsState({    this.themeMode = ThemeMode.light,    required this.locale,  });  SettingsState copyWith({    ThemeMode? themeMode,    Locale? locale,  }) {    return SettingsState(      themeMode: themeMode ?? this.themeMode,      locale: locale ?? this.locale,    );  }}